'use strict';
const BASE='http://127.0.0.1:3001/api/google-flow/bridge';
let lastTickAt=0,wakeFailures=0;
chrome.runtime.onMessage.addListener((m,sender,respond)=>{if(m.type==='localPair'){const u=new URL(sender.url);if(u.protocol!=='http:'||!['localhost','127.0.0.1'].includes(u.hostname)||u.port!=='3001'||!/^[a-f0-9]{64}$/.test(m.key))return;chrome.storage.local.set({key:m.key}).then(()=>respond({paired:true}));return true}if(!['tick','result'].includes(m.type))return;(async()=>{const config=await chrome.storage.local.get(['key','activeTab','channel']);if(!config.key){const r=await fetch('http://127.0.0.1:3001/api/google-flow/pairing',{method:'POST'});if(!r.ok)return{inactive:true};const d=await r.json();config.key=d.key;await chrome.storage.local.set({key:d.key})}if(sender.tab?.id!==config.activeTab){let old;try{old=await chrome.tabs.get(config.activeTab)}catch{}const stale=!old||Date.now()-lastTickAt>90000;if(!stale)return{inactive:true};config.activeTab=sender.tab.id;config.channel=crypto.randomUUID();await chrome.storage.local.set({activeTab:config.activeTab,channel:config.channel})}lastTickAt=Date.now();const url=new URL(sender.url);if(url.protocol!=='https:'||!['flow.google.com','labs.google'].includes(url.hostname))throw Error('Không phải tab Flow.');const route=m.type==='tick'?'/tick':'/result',body=m.type==='tick'?{...m.state,channel:config.channel}:{...m.result,channel:config.channel};let r=await fetch(BASE+route,{method:'POST',headers:{Authorization:'Bearer '+config.key,'Content-Type':'application/json'},body:JSON.stringify(body)});if(r.status===403){const p=await fetch('http://127.0.0.1:3001/api/google-flow/pairing',{method:'POST'});if(p.ok){const d=await p.json();config.key=d.key;await chrome.storage.local.set({key:d.key});r=await fetch(BASE+route,{method:'POST',headers:{Authorization:'Bearer '+config.key,'Content-Type':'application/json'},body:JSON.stringify(body)})}}if(!r.ok)throw Error('Mở Monday và kiểm tra mã ghép nối.');return r.json()})().then(respond).catch(e=>respond({error:e.message}));return true});

// Wake the paired content script from the extension worker so hidden-tab timer
// throttling cannot stall a command. No generation commands are replayed here.
let waking=false;
setInterval(async()=>{if(waking)return;waking=true;try{const c=await chrome.storage.local.get(['activeTab','key']);if(c.key&&Number.isInteger(c.activeTab)){try{await chrome.tabs.sendMessage(c.activeTab,{type:'monday-flow-wake'})}catch{}try{const r=await chrome.tabs.sendMessage(c.activeTab,{type:'monday-flow-ping'});if(r&&r.pong)wakeFailures=0}catch(e){if(/Could not establish connection|Receiving end does not exist/i.test(e.message||'')){wakeFailures++;if(wakeFailures>=3){await chrome.storage.local.remove(['activeTab','channel']);wakeFailures=0;lastTickAt=0}}}}}catch{}finally{waking=false}},5000);

let flowDownload=null;
chrome.runtime.onMessage.addListener((m,sender,reply)=>{if(!['armDownload','downloadState'].includes(m.type))return;(async()=>{const c=await chrome.storage.local.get(['activeTab']);if(sender.tab?.id!==c.activeTab||!/^https:\/\/flow\.google\.com\/project\//.test(sender.url||''))throw Error('Sai tab tải kết quả.');if(m.type==='armDownload'){flowDownload={jobId:m.jobId,started:Date.now(),id:null};return{armed:true}}if(flowDownload?.jobId!==m.jobId)throw Error('Sai lượt tải.');if(!flowDownload.id)return{done:false};const [d]=await chrome.downloads.search({id:flowDownload.id});if(d?.state==='interrupted')throw Error('Chrome không tải xong video: '+d.error);return d?.state==='complete'?{done:true,path:d.filename}:{done:false}})().then(reply).catch(e=>reply({error:e.message}));return true});
chrome.downloads.onCreated.addListener(d=>{if(!flowDownload||flowDownload.id||Date.now()-flowDownload.started>15000)return;const from=d.referrer||'',url=d.finalUrl||d.url||'';if(!from.startsWith('https://flow.google.com/')&&!/^(?:blob:)?https:\/\/(?:flow\.google\.com|[^/]*googleusercontent\.com)\//.test(url))return;if(!url.startsWith('blob:https://flow.google.com/')&&!/video|octet-stream/i.test(d.mime||'')&&!/\.mp4(?:[?]|$)/i.test(d.filename||url))return;flowDownload.id=d.id});
